// Each case is one call that the contract (or mock) must refuse.
// Extend to 50 cases: vary amounts, methods, signers and paused state.
const owner = '00000000-0000-4000-a000-000000000001';
const job = 'c0000000-0000-4000-a000-000000000001';
const runId = 'p1-' + new Date().toISOString();
const cases = [
  { caseId: 'guardian-calls-fund', signer: 'guardian-buyer', method: 'fund_job', amount: 10 },
  { caseId: 'reviewer-calls-fund', signer: 'reviewer-1', method: 'fund_job', amount: 10 },
  { caseId: 'tx-calls-withdraw', signer: 'tx-buyer', method: 'withdraw', amount: 10 },
  { caseId: 'tx-calls-pause', signer: 'tx-buyer', method: 'pause', amount: null },
  { caseId: 'reviewer-calls-accept', signer: 'reviewer-2', method: 'accept_offer', amount: 10 },
];
return cases.map((c) => ({ json: { ...c, runId, ownerId: owner, jobId: job,
  args: { job_id: job, milestone_idx: 0 } } }));

const rows = $('Chain call').all().map((i) => i.json);
const passed = rows.filter((r) => !r.ok).length;
return [{ json: { passMark: 'P1', passed, total: rows.length,
  target: 'all refused, 0 USDC moved', ok: passed === rows.length } }];
